import java.time.Duration;
import java.time.LocalDate;
import java.time.Period;
import java.time.LocalDateTime;

public class TemporalDemo {
    public static void main(String[] args) {
        // Period for calendar-based calculations
        LocalDate birthDate = LocalDate.of(1990, 5, 15);
        LocalDate currentDate = LocalDate.now();
        Period age = Period.between(birthDate, currentDate);
        System.out.printf("Age: %d years, %d months, %d days\n", 
            age.getYears(), age.getMonths(), age.getDays());

        // Duration for exact time-based calculations
        LocalDateTime start = LocalDateTime.now();
        // simulate task
        LocalDateTime end = start.plusHours(2).plusMinutes(30);
        Duration elapsed = Duration.between(start, end);
        System.out.printf("Elapsed seconds: %d\n", elapsed.getSeconds());
    }
}
